#!/usr/bin/env python3
"""Turn the ids recovered by extract_protocol.py into a Python module."""
import json, sys

data = json.load(open("tools/protocol_ids.json"))
tc = {int(k): v for k, v in data["TOCLIENT_#0"].items() if v != "TOCLIENT_NULL"}
ts = {int(k): v for k, v in data["TOSERVER_#6"].items() if v != "TOSERVER_NULL"}

with open("luantibot/commands.py", "w") as f:
    f.write('"""Protocol command ids.\n\n'
            'Generated by tools/extract_protocol.py from the Luanti 5.16.1 client\n'
            'binary\'s own command tables -- do not hand-edit.\n"""\n\n')
    for title, table in (("TOCLIENT", tc), ("TOSERVER", ts)):
        for i in sorted(table):
            f.write(f"{table[i]} = 0x{i:02X}\n")
        f.write("\n")
    f.write("TOCLIENT_NAMES = {\n")
    for i in sorted(tc):
        f.write(f"    0x{i:02X}: {tc[i]!r},\n")
    f.write("}\n\nTOSERVER_NAMES = {\n")
    for i in sorted(ts):
        f.write(f"    0x{i:02X}: {ts[i]!r},\n")
    f.write("}\n")
print(f"wrote luantibot/commands.py: {len(tc)} TOCLIENT, {len(ts)} TOSERVER")
